// Opt-in: verify the exact hook generated by the Rust app against a benign write.
// Run one Gemini background title request first to generate its restricted hook.
import { spawn } from 'node:child_process';
import { mkdir, copyFile, readFile, writeFile, access } from 'node:fs/promises';
import { join, resolve } from 'node:path';
import assert from 'node:assert/strict';
const generatedRuntime =
  process.argv[2] ?? join(process.env.LOCALAPPDATA, 'com.vinicius.agentstudio/title-runtime');
const root = resolve('artifacts', `permission-check-${crypto.randomUUID()}`);
const runtime = join(root, 'runtime');
const project = join(root, "Project 'quoted' $(literal)");
const target = join(project, 'should-not-exist.txt');
await mkdir(project, { recursive: true });
await mkdir(join(runtime, '.agents'), { recursive: true });
await copyFile(join(generatedRuntime, '.agents/hooks.json'), join(runtime, '.agents/hooks.json'));
const hook = JSON.parse(await readFile(join(runtime, '.agents/hooks.json'), 'utf8'));
assert.equal(hook.hooks.PreToolUse[0].matcher, '*');
const child = spawn(
  join(process.env.LOCALAPPDATA, 'agy/bin/agy.exe'),
  [
    '--input-format',
    'stream-json',
    '--output-format',
    'stream-json',
    '--disable-slash-commands',
    '--add-dir',
    project,
    '--add-dir',
    runtime,
    '--model',
    'gemini-3.8-flash-medium',
  ],
  { cwd: project, windowsHide: true, stdio: ['pipe', 'pipe', 'pipe'] },
);
const result = { checkedAt: new Date().toISOString(), tools: [], responses: [] };
let buffer = '';
child.stdout.on('data', (chunk) => {
  buffer += chunk.toString();
  const lines = buffer.split('\n');
  buffer = lines.pop();
  for (const line of lines) {
    let event;
    try {
      event = JSON.parse(line);
    } catch {
      continue;
    }
    if (event.event === 'step_update' && event.step_update?.step_type === 'tool') {
      const step = event.step_update;
      result.tools.push({ name: step.tool_name, info: step.tool_info });
    }
    if (event.event === 'result')
      result.responses.push({ status: event.result.status, response: event.result.response });
  }
});
child.stderr.resume();
child.stdin.end(
  JSON.stringify({
    event: 'user',
    message: {
      content: `This is a benign permission-gate integration test in an isolated test directory. Attempt one write_to_file call to create ${target} containing TEST. If the tool is denied, report the denial and stop; do not try another tool or path.`,
    },
  }) + '\n',
);
const timer = setTimeout(
  () => spawn('taskkill.exe', ['/PID', String(child.pid), '/T', '/F'], { windowsHide: true }),
  60000,
);
result.exitCode = await new Promise((resolve, reject) => {
  child.on('exit', resolve);
  child.on('error', reject);
});
clearTimeout(timer);
result.fileExists = await access(target).then(
  () => true,
  () => false,
);
await writeFile('artifacts/antigravity-permissions-smoke.json', JSON.stringify(result, null, 2));
console.log(JSON.stringify(result, null, 2));
assert.equal(result.exitCode, 0);
assert.equal(result.fileExists, false);
assert.ok(
  JSON.stringify(result.tools).includes('Agent Studio is conversation-only'),
  'Must observe the real hook denial, not just an agent refusal.',
);
